def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])

    def regular(coords):
        if len(coords) < 2:
            return False
        steps = [b - a for a, b in zip(coords, coords[1:])]
        return steps[0] > 1 and all(s == steps[0] for s in steps)

    # Find the color and coordinates of the regularly spaced grid lines.
    candidates = []
    for color in set(v for row in grid for v in row):
        rows = [r for r in range(h)
                if sum(grid[r][c] == color for c in range(w)) >= 0.70 * w]
        cols = [c for c in range(w)
                if sum(grid[r][c] == color for r in range(h)) >= 0.70 * h]
        if regular(rows) and regular(cols):
            candidates.append((len(rows) * len(cols), color, rows, cols))

    if not candidates:
        return [[Counter(v for row in grid for v in row).most_common(1)[0][0]]]

    _, line_color, rows, cols = max(candidates)

    # The non-line colors at grid intersections mark the extent of the output.
    active_rows = [
        i for i, r in enumerate(rows)
        if any(grid[r][c] != line_color for c in cols)
    ]
    active_cols = [
        j for j, c in enumerate(cols)
        if any(grid[r][c] != line_color for r in rows)
    ]
    if len(active_rows) < 2 or len(active_cols) < 2:
        return [[line_color]]

    r0, r1 = active_rows[0], active_rows[-1]
    c0, c1 = active_cols[0], active_cols[-1]

    # The ordinary cell color is found away from the grid lines.
    line_rows, line_cols = set(rows), set(cols)
    interior = [
        grid[r][c]
        for r in range(h) for c in range(w)
        if r not in line_rows and c not in line_cols
    ]
    fill = Counter(interior).most_common(1)[0][0] if interior else line_color

    out = []
    for i in range(r0, r1):
        row_out = []
        for j in range(c0, c1):
            corners = [
                grid[rows[i]][cols[j]],
                grid[rows[i]][cols[j + 1]],
                grid[rows[i + 1]][cols[j]],
                grid[rows[i + 1]][cols[j + 1]],
            ]
            color = corners[0]
            if color == line_color or any(v != color for v in corners):
                color = fill
            row_out.append(color)
        out.append(row_out)
    return out
